good.code:
import { Pool } from 'pg'
import { SecretsManagerClient, GetSecretValueCommand } from '@aws-sdk/client-secrets-manager'

// No credentials in code: the SDK uses the role attached to this pod or instance.
const sm = new SecretsManagerClient({})
const out = await sm.send(new GetSecretValueCommand({ SecretId: 'prod/orders/db' }))
const { username, password } = JSON.parse(out.SecretString ?? '{}')

export const db = new Pool({ host: process.env.DB_HOST, user: username, password })
// On rotation: re-read the secret and recreate the pool (or restart) during the overlap window.
